enum Room {
  Kitchen,
  Garden,
  Bedroom,
  Attic,
}

enum Action {
  Go(room: Room),
  Look,
  Take(item: Str),
  Quit,
}

type GameState = {
  current_room: Room;
  has_key: Bool;
}

fn room_name(r: Room) -> Str {
  match r {
    Kitchen => { return "kitchen"; }
    Garden => { return "garden"; }
    Bedroom => { return "bedroom"; }
    Attic => { return "attic"; }
  }
}

fn GameState.process(self, action: Action) -> Str {
  match action {
    Go(room) => {
      current_room = room;
      return "You walk to the " + room_name(room) + ".";
    }
    Look => { return "You are in the " + room_name(current_room) + "."; }
    Take(item) => {
      if item == "key" && current_room == Room.Kitchen {
        has_key = true;
        return "You picked up the key.";
      }
      return "There is no " + item + " here.";
    }
    Quit => { return "Goodbye!"; }
  }
}

fn main() -> Int {
  var state = GameState{ current_room: Room.Kitchen; has_key: false; };
  state.process(Action.Go(Room.Garden));
  state.process(Action.Go(Room.Kitchen));
  state.process(Action.Take("key"));
  if state.has_key { return 1; }
  return 0;
}
